#!/usr/bin/env bash
# scripts/check_skill_map.sh
# The skill-layer gate: pi's first-wins resolution over the four skill layers,
# the collision rule, and the shipped-layer link boundary.
#
# The layer model is stated in docs/adr/skill_layer_resolution.md and
# docs/reference/agent_workflow.md. The map is generated by
# scripts/skill_map.mjs; it is never committed.
#
# Test seam: SKILL_MAP_SCAN_ROOT points the scan at a fixture root.
#
# Exit codes: 0 = no hard finding, 1 = a hard finding or the gate could not run.
# Warnings are printed and do not fail the gate.

set -uo pipefail

SECONDS=0

REPO_ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
SCANNER="$REPO_ROOT/scripts/skill_map.mjs"
SCAN_ROOT="${SKILL_MAP_SCAN_ROOT:-$REPO_ROOT}"

if ! command -v node >/dev/null 2>&1; then
  echo "Skill layer gate: node is not on PATH; cannot read the layers." >&2
  exit 1
fi

if [[ ! -f "$SCANNER" ]]; then
  echo "Skill layer gate: $SCANNER is missing; cannot run." >&2
  exit 1
fi

node "$SCANNER" --root "$SCAN_ROOT"
rc=$?

if (( rc == 0 )); then
  echo "Clean (${SECONDS}s)"
else
  echo "Blocking gate: fix the findings above (see docs/adr/skill_layer_resolution.md)." >&2
fi
exit "$rc"
